INSERT INTO public.knowledge_entries (kind, project, title, body, evidence, status, origin, sources, tags, occurred_at) VALUES
('decision','ecosystem','Razul confirmed scope','Owner-only independent platform: ecosystem memory/history, public-web research, and authorized watcher/Sentinel agents with individually scoped access into assigned projects. Supersedes the initial game-QA-only framing.','reported','confirmed','recovered_brief','[{"label":"Owner brief 2026-10-31 (chat)"},{"url":"https://app.notion.com/p/40ac11610306812e986bedc0cbebf092","note":"not shared with integration; not fetched"}]','{razul,scope,recovered}','2026-10-31'),
('decision','ecosystem','Initial game-QA framing superseded','Razul began as "Game Development Observer" (animation snapping, foot sliding, clipping, collision, horse/chariot, perf, desync). QA tracking stays as one capability, not the whole role.','reported','superseded','recovered_brief','[{"label":"Owner brief 2026-10-31 (chat)"}]','{razul,scope,history}',NULL),
('decision','ecosystem','Human login is owner-only','No public registration and no human reviewer invites. Agents use separate per-agent machine identities with per-project grants, expiry, revocation and audit.','reported','confirmed','recovered_brief','[{"label":"Owner clarification (chat)"}]','{access,recovered}',NULL),
('decision','ecosystem','Agent roles: Sentinel / AngelTech / DemonTech','Sentinels: project health, diagnostics, approved routine ops, reports. AngelTech: discovery/optimization scouts. DemonTech: authorized security inspection only.','reported','confirmed','recovered_brief','[{"label":"Owner clarification (chat)"}]','{agents,roles,recovered}',NULL),
('history','ecosystem','Proposed titles: Agent Hub/Builder manager, Director of Agent Development and Community Innovation','These titles were proposals in earlier conversations, not locked roles.','reported','proposed','recovered_brief','[{"label":"Recovered conversation (owner brief 2026-10-31)"}]','{titles,recovered}',NULL),
('decision','ecosystem','Community agents separate from internal official council','Community agents stay separate from the internal official council and never inherit owner permissions.','reported','confirmed','recovered_brief','[{"label":"Recovered conversation (owner brief 2026-10-31)"}]','{community,access,recovered}',NULL),
('history','ecosystem','Terminal design: public/community vs owner/local','Earlier terminal design separates public/community interaction from full owner/local coordination.','reported','proposed','recovered_brief','[{"label":"Recovered conversation (owner brief 2026-10-31)"}]','{terminal,recovered}',NULL),
('decision','jackboy','Jackboy split: AI vs Universal, shared Nucleus','Jackboy AI evaluates/maintains AI agents and models. Jackboy Universal handles apps, sites, servers, databases and infrastructure. Both share Jackboy Nucleus. Jackboy overall: coding/architecture/testing/integration.','reported','confirmed','recovered_brief','[{"label":"Recovered conversation (owner brief 2026-10-31)"}]','{jackboy,recovered}',NULL),
('decision','ecosystem','Ecosystem roles: OMNI, Guardian, JAX','OMNI orchestrates. Guardian handles permissions/security. JAX is a conceptual peer. No live connection from Razul to any of them yet.','reported','confirmed','recovered_brief','[{"label":"Owner clarification (chat)"}]','{omni,guardian,jax,recovered}',NULL);