ALTER TABLE public.knowledge_entries ADD COLUMN IF NOT EXISTS status text NOT NULL DEFAULT 'confirmed';
ALTER TABLE public.knowledge_entries ADD COLUMN IF NOT EXISTS origin text NOT NULL DEFAULT 'entry';
ALTER TABLE public.knowledge_entries ADD CONSTRAINT knowledge_status_chk CHECK (status IN ('confirmed','proposed','superseded'));
ALTER TABLE public.knowledge_entries ADD CONSTRAINT knowledge_origin_chk CHECK (origin IN ('entry','recovered_brief'));
ALTER TABLE public.knowledge_entries DROP CONSTRAINT knowledge_author;
ALTER TABLE public.knowledge_entries ADD CONSTRAINT knowledge_author CHECK (author_user IS NOT NULL OR agent_id IS NOT NULL OR origin = 'recovered_brief');

